# SPDX-License-Identifier: Apache-2.0
"""SPDX license lines in the files written for this project.

    python3 tools/spdx.py           list the source files that lack the line
    python3 tools/spdx.py --add     add it to them

A source file is a tracked file of a kind with line comments (Python, shell,
make, Tcl, SDC, SBY, MCY, SystemVerilog, Verilog, C, C++, TSE specs) that
the project wrote: Tiny Tapeout template files nobody changed since the
import commit are left out, and so are generated files (a "do not edit" or
"generated by" note in their first lines), which get the line from their
generator or not at all. The hardware sources and the ISA (src/*.sv,
src/*.v, isa/) are left out by default and listed with --rtl. The line
goes first, or right after a "#!" line; in a TSE spec it goes last,
since spec line numbers are part of the compiler's diagnostics.

Exit status 0 when every file has the line, 1 otherwise (after --add, 0).
"""
import argparse
import os
import subprocess
import sys

LICENSE = "Apache-2.0"
TAG = "SPDX-License-Identifier:"
HASH = {".py", ".sh", ".mk", ".tcl", ".sdc", ".sby", ".mcy"}
SLASH = {".sv", ".v", ".svh", ".vh", ".c", ".h", ".cpp", ".hpp", ".tse"}
HASH_NAMES = ("Makefile",)
GENERATED = ("do not edit", "generated by")
TAIL = (".tse",)
HEAD = 6


def git(root, *args):
    return subprocess.run(("git",) + args, cwd=root, check=True, capture_output=True).stdout.decode()


def prefix(path):
    base = os.path.basename(path)
    ext = os.path.splitext(base)[1]
    if ext in HASH or base.startswith(HASH_NAMES):
        return "# "
    if ext in SLASH:
        return "// "
    return None


def rtl(path):
    return path.startswith("isa/") or (path.startswith("src/") and path.endswith((".sv", ".v")))


def sources(root, with_rtl):
    tmpl = git(root, "rev-list", "--max-parents=0", "HEAD").split()[-1]
    tmpl_files = set(git(root, "ls-tree", "-r", "--name-only", tmpl).splitlines())
    changed = set(git(root, "diff", "--name-only", tmpl).splitlines())
    for path in git(root, "ls-files").splitlines():
        if prefix(path) is None or (path in tmpl_files and path not in changed):
            continue
        if rtl(path) and not with_rtl:
            continue
        full = os.path.join(root, path)
        if not os.path.isfile(full) or os.path.islink(full):
            continue
        yield path, full


def generated(head):
    """A comment line in the head that says the file is generated."""
    for line in head:
        text = line.strip().lstrip("#/* ").lower()
        if text.startswith(GENERATED[1]) or (GENERATED[0] in text and "generated" in text):
            return True
    return False


def missing(text):
    head = text.split("\n", HEAD)[:HEAD]
    tail = text.rstrip("\n").rsplit("\n", 2)[-2:]
    return TAG not in "\n".join(head + tail) and not generated(head)


def add(full, pre):
    text = open(full, encoding="utf-8").read()
    line = pre + TAG + " " + LICENSE + "\n"
    if full.endswith(TAIL):
        text = (text if text.endswith("\n") or not text else text + "\n") + line
    elif text.startswith("#!"):
        first, _, rest = text.partition("\n")
        text = first + "\n" + line + rest
    else:
        text = line + text
    with open(full, "w", encoding="utf-8") as f:
        f.write(text)


def main(argv=None):
    ap = argparse.ArgumentParser(description="SPDX license lines")
    ap.add_argument("--add", action="store_true", help="add the line where it is missing")
    ap.add_argument("--rtl", action="store_true", help="also cover src/*.sv, src/*.v and isa/")
    ap.add_argument("-C", dest="root", default=".")
    a = ap.parse_args(argv)
    root = git(a.root, "rev-parse", "--show-toplevel").strip()
    todo = [(p, f) for p, f in sources(root, a.rtl)
            if missing(open(f, encoding="utf-8", errors="replace").read())]
    for path, full in todo:
        if a.add:
            add(full, prefix(path))
        else:
            sys.stdout.write(path + "\n")
    if todo and not a.add:
        sys.stdout.write("spdx: %d file(s) without the line\n" % len(todo))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
